var longestAlternating = function(nums) {
    const n = nums.length;
    if (n <= 1) return n;

    // Step 1: up[i] / down[i] = alternating run ending at i whose last step is up / down
    const up = new Array(n).fill(1);
    const down = new Array(n).fill(1);

    for (let i = 1; i < n; i++) {
        if (nums[i - 1] < nums[i]) {
            up[i] = down[i - 1] + 1;
        } else if (nums[i - 1] > nums[i]) {
            down[i] = up[i - 1] + 1;
        }
    }

    // Step 2: runs starting at i whose first step is up / down
    const rUp = new Array(n).fill(1);
    const rDown = new Array(n).fill(1);

    for (let i = n - 2; i >= 0; i--) {
        if (nums[i] < nums[i + 1]) {
            rUp[i] = rDown[i + 1] + 1;
        } else if (nums[i] > nums[i + 1]) {
            rDown[i] = rUp[i + 1] + 1;
        }
    }

    // Step 3: best with no removal
    let ans = 1;
    for (let i = 0; i < n; i++) {
        ans = Math.max(ans, up[i], down[i]);
    }

    // Step 4: remove nums[p]; the glued step must be opposite to the left run's
    // last step and to the right run's first step (equal neighbours never glue)
    for (let p = 1; p < n - 1; p++) {
        if (nums[p - 1] < nums[p + 1]) {
            ans = Math.max(ans, down[p - 1] + rDown[p + 1]);
        } else if (nums[p - 1] > nums[p + 1]) {
            ans = Math.max(ans, up[p - 1] + rUp[p + 1]);
        }
    }

    return ans;
};

