// Same idea run forward in one pass: a run ending at i is tracked by the direction of
// its last step and by whether the one removal has already been spent.
func longestAlternating(nums []int) int {
	n := len(nums)
	if n == 0 {
		return 0
	}

	inc0 := make([]int, n) // last step up, no removal used
	dec0 := make([]int, n) // last step down, no removal used
	inc1 := make([]int, n) // last step up, removal used
	dec1 := make([]int, n) // last step down, removal used

	maxLen := 1
	// i = 0, single element subarray
	inc0[0] = 1
	dec0[0] = 1
	inc1[0] = 1
	dec1[0] = 1

	for i := 1; i < n; i++ {
		greater := nums[i] > nums[i-1]
		less := nums[i] < nums[i-1]

		// Step 1: no removal: extend the run ending at i-1 if the step alternates
		if greater {
			inc0[i] = dec0[i-1] + 1
			dec0[i] = 1
		} else if less {
			dec0[i] = inc0[i-1] + 1
			inc0[i] = 1
		} else {
			inc0[i] = 1
			dec0[i] = 1
		}

		// Step 2: removal already spent earlier: extend the same way
		inc1[i] = 1
		dec1[i] = 1

		// Extend from a state that already used the deletion
		if greater {
			inc1[i] = max(inc1[i], dec1[i-1]+1)
		} else if less {
			dec1[i] = max(dec1[i], inc1[i-1]+1)
		}

		// Step 3: spend the removal on nums[i-1]: glue nums[i-2] to nums[i];
		// the glued step must be opposite to the run ending at i-2
		if i >= 2 {
			if nums[i] > nums[i-2] {
				inc1[i] = max(inc1[i], dec0[i-2]+1)
			}
			if nums[i] < nums[i-2] {
				dec1[i] = max(dec1[i], inc0[i-2]+1)
			}
		}

		// Step 4: the answer is the best of all four states
		maxLen = max(maxLen, inc0[i])
		maxLen = max(maxLen, dec0[i])
		maxLen = max(maxLen, inc1[i])
		maxLen = max(maxLen, dec1[i])
	}

	return maxLen
}

func max(a, b int) int {
	if a > b {
		return a
	}
	return b
}
